#include "fates/graphics/event_camera.hpp"
#include "fates/detail/principal_camera_runtime.hpp"
EventCamera::EventCamera(const CameraTrack*t):track_(t){fates::decomp_detail::EventCameraBuildTrack(*this,t);} EventCamera::~EventCamera()=default; void EventCamera::Tick(){fates::decomp_detail::EventCameraTick(*this);} void EventCamera::Enter(){fates::decomp_detail::EventCameraEnter(*this);} void EventCamera::Leave(){fates::decomp_detail::EventCameraLeave(*this);} void EventCamera::GetInitialEyeAt(nn::math::VEC3&e,nn::math::VEC3&a){if(track_&&!track_->keys.empty()){e=track_->keys.front().eye;a=track_->keys.front().at;}else{e={};a={};}} void EventCamera::SetFarClipExpandPoint(const nn::math::VEC3&p,float r){fates::decomp_detail::SetEventFarClipExpandPoint(p,r);} void EventCamera::ResetFarClipExpandPoint(){fates::decomp_detail::ResetEventFarClipExpandPoint();} int EventCamera::GetModeType()const{return 0;} bool EventCamera::CanChangeMode()const{return false;} bool EventCamera::CanLookAround()const{return canLookAround_;} bool EventCamera::IsHitPos()const{return hitPos_;} bool EventCamera::IsHitArea()const{return false;} bool EventCamera::IsHitFovy()const{return false;} bool EventCamera::IsPlaying()const{return loop_||frame_<endFrame_;}
